-- GATE PACK 0255 anon_predicate_policies (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select 'anon_predicate_policies' as k, pg_catalog.count(*)::text as v
from pg_catalog.pg_policy pol
join pg_catalog.pg_class c on c.oid = pol.polrelid
where c.relnamespace = 'public'::pg_catalog.regnamespace and (pol.polroles = array[0]::pg_catalog.oid[] or (select r.oid from pg_catalog.pg_roles r where r.rolname = 'anon') = any (pol.polroles))
  and pg_catalog.lower(coalesce(pg_catalog.pg_get_expr(pol.polqual, pol.polrelid), '') || ' ' || coalesce(pg_catalog.pg_get_expr(pol.polwithcheck, pol.polrelid), '')) ~ '(^|[^a-z_])(is_studio_member|is_studio_owner|session_is_visible)\(';
